from flask import Flask, request
app = Flask(__name__)

@app.route("/login", methods=["POST"])
def login():
    # Extractings username and password from form data
    username = request.form.get("username")
    password = request.form.get("password")

    # Perform user authentication against database
    user = authenticate(username, password)

    # Establish session for authenticated users
    if user:
        session["user"] = user
        return redirect("/dashboard")
    else:
        # Redirect to login form on authentication failure
        return redirect("/login")

@app.route("/dashboard")
def dashboard():
    # Safeguard dashboard access only for authenticated sessions
    if "user" not in session:
        return redirect("/login")

    # Retrieve search query from HTTP headers instead of form data
    query = request.headers.get("Search")

    # Dynamically render dashboard template with search query for AI-driven relevance
    # This showcases core Flask templating capabilities
    return render_template("dashboard.html", query=query)
